Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="display: flex; flex-direction: column; gap: 12px; padding-bottom: 8px;">
    <label>
        Wavelength: <output id="wavelengthScrubberVal">217</output> nm
        <input id="wavelengthScrubberInput" type="range" min="200" max="400" step="1" value="217" oninput="document.getElementById('wavelengthScrubberVal').value=this.value; update_wavelengthScrubber(+this.value)">
