// @FIGURE_CODE_BEGIN
let state = {
    wavelengthScrubber: 217,
    regionHighlight: 'Full spectrum'
};

const steps = [
    {
        title: "UV Absorption Spectrum",
        narration: "This spectrum plots how strongly 1,3-butadiene absorbs ultraviolet light across different wavelengths.",
        state: { wavelengthScrubber: 217, regionHighlight: "Full spectrum" }
    },
    {
        title: "Finding \u03BB_max",
        narration: "Use the slider to trace the curve. The absorbance reaches its absolute maximum at 217 nm, identifying this as the compound's \u03BB_max.",
        state: { wavelengthScrubber: 217, regionHighlight: "Full spectrum" }
    },
    {
        title: "The Absorption Peak",
        narration: "The vast majority of the UV absorption occurs in a narrow, steep band between 200 and 250 nm.",
        state: { wavelengthScrubber: 217, regionHighlight: "Peak (200-250 nm)" }
    },
    {
        title: "The Transparent Tail",
        narration: "Beyond 250 nm, the absorbance drops to near zero, indicating that the molecule is essentially transparent to longer UV wavelengths.",
        state: { wavelengthScrubber: 350, regionHighlight: "Tail (>250 nm)" }
    }
];

let currentStep = 0;

// Mathematical model matching the provided spectrum's precise curve shapes
function getAbsorbance(x) {
    if (x <= 217) {
        // Steeper Gaussian onset for the leading edge
        return 0.86 * Math.exp(-0.00321 * (x - 217) * (x - 217));
    } else {
        // Fast decay mixed with a slow transparent tail
        let dx = x - 217;
        return 0.83 * Math.exp(-0.08 * dx) + 0.03 * Math.exp(-0.001 * dx);
    }
}

const curveData = [];
for (let x = 200; x <= 400; x++) {
    curveData.push({ x: x, y: getAbsorbance(x) });
}

// Set up container and Chart.js instance
const container = document.getElementById('container');
container.innerHTML = '<canvas id="chartCanvas" style="width:100%;height:100%;display:block;"></canvas>';
const ctx = document.getElementById('chartCanvas').getContext('2d');

const customDrawPlugin = {
    id: 'customDrawPlugin',
    beforeDraw: (chart) => {
        const { ctx, chartArea } = chart;
        if (!chartArea) return;

        // 1. Pale pink gradient background matching the textbook
        const gradient = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
        gradient.addColorStop(0, '#ffebef');
        gradient.addColorStop(1, '#ffffff');
        ctx.fillStyle = gradient;
        ctx.fillRect(chartArea.left, chartArea.top, chartArea.width, chartArea.height);
    },
    afterDatasetDraw: (chart, args) => {
        const { ctx, chartArea, scales } = chart;
        if (!chartArea) return;

        // 2. Overlay a white semitransparent mask on the unhighlighted regions
        // This runs precisely between the main line and the interactive dot drawing
        if (args.index === 1 && state.regionHighlight !== 'Full spectrum') {
            ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
            if (state.regionHighlight === 'Peak (200-250 nm)') {
                let xRight = scales.x.getPixelForValue(250);
                if (xRight < chartArea.right) {
                    ctx.fillRect(xRight, chartArea.top, chartArea.right - xRight, chartArea.height);
                }
            } else if (state.regionHighlight === 'Tail (>250 nm)') {
                let xRight = scales.x.getPixelForValue(250);
                if (xRight > chartArea.left) {
                    ctx.fillRect(chartArea.left, chartArea.top, xRight - chartArea.left, chartArea.height);
                }
            }
        }
    },
    afterDraw: (chart) => {
        const { ctx, chartArea, scales } = chart;
        if (!chartArea) return;

        // 3. Render λ_max = 217 nm annotation at peak
        const xPeak = scales.x.getPixelForValue(217);
        const yPeak = scales.y.getPixelForValue(0.86);

        ctx.fillStyle = '#000';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';

        let startX = xPeak + 14;
        let startY = yPeak - 4;

        ctx.font = 'italic 15px sans-serif';
        ctx.fillText('\u03BB', startX, startY);
        let wLambda = ctx.measureText('\u03BB').width;

        ctx.font = '10px sans-serif';
        ctx.fillText('max', startX + wLambda, startY + 4);
        let wMax = ctx.measureText('max').width;

        ctx.font = '13px sans-serif';
        ctx.fillText(' = 217 nm', startX + wLambda + wMax, startY);

        // 4. Render live dot readout ensuring it doesn't clip
        let dotX = chart.data.datasets[2].data[0].x;
        let dotY = chart.data.datasets[2].data[0].y;
        let px = scales.x.getPixelForValue(dotX);
        let py = scales.y.getPixelForValue(dotY);

        ctx.save();
        let rw = 72;
        let rh = 20;
        let rx = px + 10;
        let ry = py - 26;

        // Flip to the left if too close to right edge
        if (rx + rw > chartArea.right) rx = px - rw - 10;
        // Shift down if too close to top edge
        if (ry < chartArea.top) ry = py + 10;

        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.fillRect(rx, ry, rw, rh);
        ctx.strokeStyle = '#999';
        ctx.lineWidth = 1;
        ctx.strokeRect(rx, ry, rw, rh);

        ctx.fillStyle = '#000';
        ctx.font = '11px ui-monospace, Consolas, monospace';
        ctx.fillText(`A = ${dotY.toFixed(3)}`, rx + 6, ry + 14);
        ctx.restore();

        // 5. Render axes titles and magenta directional arrows
        ctx.font = '13px sans-serif';
        ctx.fillStyle = '#000';
        ctx.textAlign = 'center';

        // X-axis setup
        let xTitle = 'Wavelength (nm)';
        let xCenter = chartArea.left + chartArea.width / 2;
        let yTextX = chartArea.bottom + 36;
        ctx.fillText(xTitle, xCenter, yTextX);

        let textWidthX = ctx.measureText(xTitle).width;
        let arrowStartX = xCenter + textWidthX / 2 + 10;
        let arrowEndX = chartArea.right;

        ctx.strokeStyle = '#c6007b';
        ctx.fillStyle = '#c6007b';
        ctx.lineWidth = 1.5;

        if (arrowEndX > arrowStartX + 12) {
            ctx.beginPath();
            ctx.moveTo(arrowStartX, yTextX - 4);
            ctx.lineTo(arrowEndX, yTextX - 4);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(arrowEndX, yTextX - 4);
            ctx.lineTo(arrowEndX - 6, yTextX - 8);
            ctx.lineTo(arrowEndX - 6, yTextX);
            ctx.fill();
        }

        // Y-axis setup (requires canvas rotation)
        ctx.save();
        ctx.translate(chartArea.left - 42, chartArea.top + chartArea.height / 2);
        ctx.rotate(-Math.PI / 2);
        let yTitle = 'Absorbance';
        ctx.fillText(yTitle, 0, 0);
        let textWidthY = ctx.measureText(yTitle).width;
        ctx.restore();

        let yArrowStartX = chartArea.left - 46; 
        let yArrowStartY = chartArea.top + chartArea.height / 2 - textWidthY / 2 - 10;
        let yArrowEndY = chartArea.top;

        if (yArrowStartY > yArrowEndY + 12) {
            ctx.beginPath();
            ctx.moveTo(yArrowStartX, yArrowStartY);
            ctx.lineTo(yArrowStartX, yArrowEndY);
            ctx.stroke();

            ctx.beginPath();
            ctx.moveTo(yArrowStartX, yArrowEndY);
            ctx.lineTo(yArrowStartX - 4, yArrowEndY + 6);
            ctx.lineTo(yArrowStartX + 4, yArrowEndY + 6);
            ctx.fill();
        }
    }
};

const chart = new Chart(ctx, {
    type: 'line',
    data: {
        datasets: [
            {
                label: 'Highlight Fill',
                data: [],
                borderColor: 'transparent',
                backgroundColor: 'rgba(198, 0, 123, 0.15)',
                fill: 'origin',
                pointRadius: 0,
                pointHitRadius: 0,
                order: 3
            },
            {
                label: 'Spectrum Trace',
                data: curveData,
                borderColor: '#c6007b',
                borderWidth: 2,
                fill: false,
                pointRadius: 0,
                pointHitRadius: 0,
                order: 2
            },
            {
                label: 'Live Scrubber Dot',
                data: [{ x: 217, y: 0.86 }],
                backgroundColor: '#c6007b',
                borderColor: '#fff',
                borderWidth: 1.5,
                pointRadius: 4.5,
                showLine: false,
                order: 1
            }
        ]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        layout: {
            padding: {
                left: 58,
                bottom: 48,
                top: 25,
                right: 25
            }
        },
        plugins: {
            legend: { display: false },
            tooltip: { enabled: false }
        },
        scales: {
            x: {
                type: 'linear',
                min: 200,
                max: 400,
                ticks: { stepSize: 20 },
                title: { display: false },
                grid: { drawOnChartArea: false, drawTicks: true }
            },
            y: {
                type: 'linear',
                min: 0,
                max: 1.0,
                ticks: { stepSize: 0.2 },
                title: { display: false },
                grid: { drawOnChartArea: false, drawTicks: true }
            }
        },
        animation: { duration: 250, easing: 'easeOutQuart' }
    },
    plugins: [customDrawPlugin]
});

window.__markRendered();

window.update_wavelengthScrubber = function(val) {
    state.wavelengthScrubber = val;
    chart.data.datasets[2].data[0] = { x: val, y: getAbsorbance(val) };
    chart.update();
};

window.update_regionHighlight = function(val) {
    state.regionHighlight = val;
    if (val === 'Peak (200-250 nm)') {
        chart.data.datasets[0].data = curveData.filter(p => p.x >= 200 && p.x <= 250);
    } else if (val === 'Tail (>250 nm)') {
        chart.data.datasets[0].data = curveData.filter(p => p.x >= 250 && p.x <= 400);
    } else {
        chart.data.datasets[0].data = [];
    }
    chart.update();
};

function applyStateToUI() {
    document.getElementById('wavelengthScrubberInput').value = state.wavelengthScrubber;
    document.getElementById('wavelengthScrubberVal').value = state.wavelengthScrubber;
    document.getElementById('regionHighlightInput').value = state.regionHighlight;

    update_wavelengthScrubber(state.wavelengthScrubber);
    update_regionHighlight(state.regionHighlight);
}

function updateDemoPlayer() {
    document.getElementById('demoNarration').innerHTML = `<strong>${steps[currentStep].title}:</strong> ${steps[currentStep].narration}`;
    document.getElementById('stepLabel').textContent = `${currentStep + 1} / ${steps.length}`;
}

window.prevStep = function() {
    if (currentStep > 0) {
        currentStep--;
        Object.assign(state, steps[currentStep].state);
        applyStateToUI();
        updateDemoPlayer();
    }
};

window.nextStep = function() {
    if (currentStep < steps.length - 1) {
        currentStep++;
        Object.assign(state, steps[currentStep].state);
        applyStateToUI();
        updateDemoPlayer();
    }
};

// Initialize default state
updateDemoPlayer();
// @FIGURE_CODE_END

